import { useRef, useState, useEffect, useCallback } from 'react'
import { getOwnerUserList, PlatformUserTypes } from '@/apis/admin/platform-user'
import {
    PageContainer,
    ProCard,
    ProForm,
    ProFormInstance,
    ProFormDigit,
    ProFormSwitch,
} from '@ant-design/pro-components'
import {
    Button,
    message,
    Space,
    Row,
    Col,
    Alert,
    Form,
    Input,
    InputNumber,
    Select,
    Spin,
} from 'antd'
import {
    SaveOutlined,
    ReloadOutlined,
    GiftOutlined,
    SettingOutlined,
    UserOutlined,
    CarOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import type { BaseOptionType } from 'antd/es/select'

const PAGE_SIZE = 50

interface UserOption extends BaseOptionType {
    value: number
    label: React.ReactNode
    user: PlatformUserTypes.AiPostOwnerUserListDto
}

const PointsSetting: React.FC = () => {
    const formRef = useRef<ProFormInstance>()
    const [grantForm] = Form.useForm()
    const [loading, setLoading] = useState(false)
    const [saving, setSaving] = useState(false)
    const [granting, setGranting] = useState(false)

    // 用户下拉相关状态
    const [userOptions, setUserOptions] = useState<UserOption[]>([])
    const [userLoading, setUserLoading] = useState(false)
    const [userPage, setUserPage] = useState(1)
    const [userTotal, setUserTotal] = useState(0)
    const [userSearchKey, setUserSearchKey] = useState('')
    const userFetchLock = useRef(false)

    // 加载用户列表（分页+搜索）
    const loadUserList = useCallback(async (page: number = 1, searchKey: string = '', isLoadMore: boolean = false) => {
        if (userFetchLock.current) return
        userFetchLock.current = true

        try {
            setUserLoading(true)
            const res = await getOwnerUserList({
                page,
                pageSize: PAGE_SIZE,
                nickname: searchKey || undefined,
                phone: /^\d+$/.test(searchKey) ? searchKey : undefined,
            })
            if (res.code === ResultEnum.SUCCESS && res.data?.list) {
                const newOptions: UserOption[] = res.data.list.map(user => ({
                    value: user.id,
                    label: (
                        <Space>
                            <UserOutlined />
                            {user.nickname}（{user.phone}）
                        </Space>
                    ),
                    user,
                }))

                if (isLoadMore) {
                    setUserOptions(prev => [...prev, ...newOptions])
                } else {
                    setUserOptions(newOptions)
                }
                setUserPage(res.data.page)
                setUserTotal(res.data.totalCount)
            }
        } catch (e) {
            console.error('加载用户列表失败:', e)
        } finally {
            setUserLoading(false)
            userFetchLock.current = false
        }
    }, [])

    // 初始化加载
    useEffect(() => {
        loadUserList(1, '', false)
        // 初始化表单默认值
        formRef.current?.setFieldsValue({
            normalSignup: 100,
            deliverySignup: 200,
            exchangePoints: 100,
            exchangeCents: 100,
            expiryDays: 365,
            refundOnCancel: true
        })
    }, [loadUserList])

    // 处理下拉滚动加载
    const handlePopupScroll = (e: React.UIEvent<HTMLDivElement>) => {
        const { target } = e
        const scrollTop = (target as HTMLDivElement).scrollTop
        const scrollHeight = (target as HTMLDivElement).scrollHeight
        const clientHeight = (target as HTMLDivElement).clientHeight

        // 滚动到底部时加载下一页
        if (scrollHeight - scrollTop - clientHeight < 50) {
            const hasMore = userOptions.length < userTotal
            if (hasMore && !userLoading) {
                loadUserList(userPage + 1, userSearchKey, true)
            }
        }
    }

    // 处理搜索
    const handleSearch = (value: string) => {
        setUserSearchKey(value)
        setUserPage(1)
        loadUserList(1, value, false)
    }

    // 保存规则
    const handleSaveRules = async () => {
        try {
            const values = await formRef.current?.validateFields()
            setSaving(true)
            // 这里应该调用保存接口
            console.log('保存积分规则:', values)
            message.success('积分规则已保存，修改对后续订单生效')
        } catch (e) {
            console.error(e)
        } finally {
            setSaving(false)
        }
    }

    // 恢复默认
    const handleReset = () => {
        formRef.current?.setFieldsValue({
            normalSignup: 100,
            deliverySignup: 200,
            exchangePoints: 100,
            exchangeCents: 100,
            expiryDays: 365,
            refundOnCancel: true
        })
        message.success('已恢复当前默认配置')
    }

    // 手工赠送积分
    const handleGrant = async () => {
        try {
            const values = await grantForm.validateFields()
            setGranting(true)

            if (!values.userId) {
                message.error('请选择用户')
                setGranting(false)
                return
            }
            if (!values.points || values.points <= 0) {
                message.error('请输入有效的积分值')
                setGranting(false)
                return
            }
            if (!values.reason) {
                message.error('请输入赠送原因')
                setGranting(false)
                return
            }

            // 这里应该调用赠送接口
            console.log('手工赠送积分:', values)
            message.success('手工赠送成功，已写入积分流水')
            grantForm.resetFields()
        } catch (e) {
            console.error(e)
        } finally {
            setGranting(false)
        }
    }

    return (
        <PageContainer
            header={{
                title: (
                    <Space>
                        <SettingOutlined style={{ color: '#1890ff' }} />
                        <span style={{ fontSize: 20, fontWeight: 600 }}>积分设置</span>
                    </Space>
                ),
                breadcrumb: undefined,
            }}
        >
            <Space direction="vertical" size="large" style={{ width: '100%' }}>
                {/* 基础规则配置 */}
                <ProCard
                    title={
                        <Space>
                            <SettingOutlined style={{ color: '#1890ff' }} />
                            基础规则配置
                        </Space>
                    }
                    bordered
                    headerBordered
                    extra={
                        <Space>
                            <Button
                                icon={<ReloadOutlined />}
                                onClick={handleReset}
                            >
                                恢复默认
                            </Button>
                            <Button
                                type="primary"
                                icon={<SaveOutlined />}
                                onClick={handleSaveRules}
                                loading={saving}
                            >
                                保存规则
                            </Button>
                        </Space>
                    }
                >
                    <ProForm
                        formRef={formRef}
                        submitter={false}
                        layout="horizontal"
                        labelCol={{ flex: '0 0 150px' }}
                        wrapperCol={{ flex: '1 1 auto' }}
                        labelAlign="right"
                        loading={loading}
                    >
                        <Row gutter={24}>
                            <Col span={12}>
                                <ProFormDigit
                                    name="normalSignup"
                                    label="用户注册赠送积分"
                                    min={0}
                                    fieldProps={{
                                        style: { width: 160 },
                                        addonAfter: '积分'
                                    }}
                                    rules={[{ required: true, message: '请输入积分值' }]}
                                />
                            </Col>
                            <Col span={12}>
                                <ProFormDigit
                                    name="deliverySignup"
                                    label="配送员注册赠送积分"
                                    min={0}
                                    fieldProps={{
                                        style: { width: 160 },
                                        addonAfter: '积分'
                                    }}
                                    rules={[{ required: true, message: '请输入积分值' }]}
                                />
                            </Col>
                        </Row>

                        <Row gutter={24}>
                            <Col span={12}>
                                <Form.Item
                                    label="兑换比率"
                                    required
                                >
                                    <Space>
                                        <ProFormDigit
                                            name="exchangePoints"
                                            noStyle
                                            min={1}
                                            fieldProps={{ style: { width: 100 } }}
                                        />
                                        <span>积分 =</span>
                                        <ProFormDigit
                                            name="exchangeCents"
                                            noStyle
                                            min={1}
                                            fieldProps={{ style: { width: 100 } }}
                                        />
                                        <span>分</span>
                                    </Space>
                                </Form.Item>
                            </Col>
                            <Col span={12}>
                                <ProFormDigit
                                    name="expiryDays"
                                    label="积分有效期"
                                    min={1}
                                    fieldProps={{
                                        style: { width: 160 },
                                        addonAfter: '天'
                                    }}
                                    rules={[{ required: true, message: '请输入有效期' }]}
                                    tooltip="按发放批次到期"
                                />
                            </Col>
                        </Row>

                        <Row gutter={24}>
                            <Col span={12}>
                                <ProFormSwitch
                                    name="refundOnCancel"
                                    label="订单取消退回已扣积分"
                                    checkedChildren="开启"
                                    unCheckedChildren="关闭"
                                />
                            </Col>
                        </Row>
                    </ProForm>

                    {/* 配送员使用规则提示 */}
                    <Alert
                        message="配送员使用规则"
                        description={'配送员注册成功后发放注册赠送积分；配送员开柜视为消费"暂存格口"商品，需按商品定价支付费用或使用积分抵扣，计费规则与普通用户一致。'}
                        type="success"
                        showIcon
                        icon={<CarOutlined />}
                        style={{ marginTop: 20 }}
                    />
                </ProCard>

                {/* 手工赠送积分 */}
                <ProCard
                    title={
                        <Space>
                            <GiftOutlined style={{ color: '#1890ff' }} />
                            手工赠送积分
                        </Space>
                    }
                    bordered
                    headerBordered
                >
                    <Form
                        form={grantForm}
                        layout="horizontal"
                        labelCol={{ flex: '0 0 100px' }}
                        wrapperCol={{ flex: '1 1 auto' }}
                        labelAlign="right"
                    >
                        <Row gutter={24}>
                            <Col span={24}>
                                <Form.Item
                                    label="用户"
                                    name="userId"
                                    rules={[{ required: true, message: '请选择用户' }]}
                                >
                                    <Select
                                        placeholder="请输入手机号或昵称搜索"
                                        showSearch
                                        allowClear
                                        onSearch={handleSearch}
                                        onPopupScroll={handlePopupScroll}
                                        style={{ maxWidth: 400 }}
                                        options={userOptions}
                                        notFoundContent={userLoading ? <Spin size="small" /> : '无匹配用户'}
                                        filterOption={false}
                                        dropdownRender={(menu) => (
                                            <>
                                                {menu}
                                                {userLoading && (
                                                    <div style={{ textAlign: 'center', padding: '8px 0' }}>
                                                        <Spin size="small" />
                                                    </div>
                                                )}
                                                {!userLoading && userOptions.length >= userTotal && userTotal > 0 && (
                                                    <div style={{ textAlign: 'center', padding: '8px 0', color: '#999', fontSize: 12 }}>
                                                        已加载全部 {userTotal} 条数据
                                                    </div>
                                                )}
                                            </>
                                        )}
                                    />
                                </Form.Item>
                            </Col>
                        </Row>

                        <Row gutter={24}>
                            <Col span={24}>
                                <Form.Item
                                    label="赠送积分"
                                    name="points"
                                    rules={[{ required: true, message: '请输入积分' }]}
                                >
                                    <InputNumber
                                        min={1}
                                        placeholder="请输入积分"
                                        style={{ maxWidth: 200 }}
                                    />
                                </Form.Item>
                            </Col>
                        </Row>

                        <Row gutter={24}>
                            <Col span={24}>
                                <Form.Item
                                    label="赠送原因"
                                    name="reason"
                                    rules={[{ required: true, message: '请输入赠送原因' }]}
                                >
                                    <Input
                                        placeholder="例如：活动补贴 / 异常补偿"
                                        style={{ maxWidth: 400 }}
                                    />
                                </Form.Item>
                            </Col>
                        </Row>

                        <Row gutter={24}>
                            <Col span={24}>
                                <Form.Item label=" " colon={false}>
                                    <Space>
                                        <Button
                                            type="primary"
                                            icon={<GiftOutlined />}
                                            onClick={handleGrant}
                                            loading={granting}
                                        >
                                            发放
                                        </Button>
                                        <span style={{ fontSize: 12, color: '#999' }}>
                                            说明：本期活动赠送通过后台手工发放实现，记录会写入积分流水。
                                        </span>
                                    </Space>
                                </Form.Item>
                            </Col>
                        </Row>
                    </Form>
                </ProCard>
            </Space>
        </PageContainer>
    )
}

export default PointsSetting
